import{_ as r,l,o as e,c as s,v as t,p as n,x as i,d as h,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"金属氧化物胶的随机机制","description":"","frontmatter":{"title":"金属氧化物胶的随机机制","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mor-stochastics.md","filePath":"litho/mor-stochastics.md","lastUpdated":1789023840000}'),p={name:"litho/mor-stochastics.md"};function c(_,a,B,A,m,u){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="金属氧化物胶的随机机制" tabindex="-1">金属氧化物胶的随机机制 <a class="header-anchor" href="#金属氧化物胶的随机机制" aria-label="Permalink to &quot;金属氧化物胶的随机机制&quot;">​</a></h1><div class="epigraph"><p>没有长程酸，随机并不消失：团簇吸不吸到、配体断不断、二次电子走多远，换成另一组可数对象。</p><footer>—— 据 Inpria 等对锡氧 / MOR 的公开原理；Naulleau 对材料离散的一般论述</footer></div><p><a href="/litho/chemical-stochastic-mitigation">上一课</a>的抑制清单默认 CAR 的 PAG/碱。<a href="/litho/tin-oxide-resist">锡氧胶</a> 已把成像换成配体解离与金属–氧网络。缺口是随机：MOR 的泊松源是什么、核剩什么、缺陷长什么样。本课钉 MOR 随机机制。干法显影（含部分 MOR 栈）留给<a href="/litho/dry-resist-develop">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CAR 的可数对象是光子、酸、碱、链。MOR（锡氧笼等）是光子、二次电子、纳米团簇、配体状态。吸收截面高，同样 \\(E\\) 下入射光子可以更少仍够事件——S 角看起来好。团簇数密度若低，每个「像素」很大，R 角被粒子尺寸钉死，低频粗糙来自团聚。没有 \\(G_a\\)，有效模糊更接近 \\(G_e\\) 与团簇半径，PEB 不再是同一颗酸核旋钮。</p><p>缺口不是重写锡氧化学，而是：OPC 与 MC 必须换抽样对象。把 CAR 的 PAG 泊松模型改个剂量标尺，会把团聚地板认成光子项。</p><h3 id="负胶工作点改悬崖口令" tabindex="-1">负胶工作点改悬崖口令 <a class="header-anchor" href="#负胶工作点改悬崖口令" aria-label="Permalink to &quot;负胶工作点改悬崖口令&quot;">​</a></h3><p>多数锡氧公开叙述是负胶：曝光区留下。欠剂量则图形缺失（该交联的没连上），过剂量则桥（不该连的连上）或难显影。桥/断口令与正胶 CAR 相反，拓扑仍是连通性。缺陷率曲线照画，只是剂量轴两侧含义要改。</p><p><span class="marginnote">铪、锆氧是同一族其他点。本课用锡氧当代表，换金属等于换吸收边、沾污门与团簇统计，不是换百科。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>拆实验：加剂量，若 LCDU 按 \\(1/\\sqrt{E}\\) 降，光子/电子项在；若很快地板，查团聚与涂布。降后烘：若谱几乎不动，说明没有 CAR 式 \\(G_a\\)。换底层：灵敏度与底部缺陷动，电子界面项在。MC：抽团簇位置与每个簇的吸收/配体事件，不要抽「连续酸场加噪声」。</p><p>沾污与颗粒是系统缺陷，会伪装成随机。重复曝光对拍仍然有效。</p>',12)),(e(),n(E,null,{default:i(()=>[d(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PH%5B%22EUV%20%E5%85%89%E5%AD%90%22%5D%20--%3E%20SE%5B%22%E4%BA%8C%E6%AC%A1%E7%94%B5%E5%AD%90%22%5D%0A%20%20CL%5B%22%E5%9B%A2%E7%B0%87%E4%BD%8D%E7%BD%AE%22%5D%20--%3E%20EV%5B%22%E9%85%8D%E4%BD%93%20%2F%20%E7%BD%91%E7%BB%9C%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20SE%20--%3E%20EV%0A%20%20EV%20--%3E%20NEG%5B%22%E8%B4%9F%E8%83%B6%E7%95%99%E4%B8%8B%E5%8C%BA%22%5D%0A%20%20AGG%5B%22%E5%9B%A2%E8%81%9A%22%5D%20--%3E%20LF%5B%22%E4%BD%8E%E9%A2%91%E7%B2%97%E7%B3%99%20%2F%20%E5%9C%B0%E6%9D%BF%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>高 Z 位点优先吸收，事件集中在簇上。簇间电子可以串话，\\(G_e\\) 造成邻近相关，不是白噪声。网络逾渗：要留下一条线，簇必须连成渗流路径；欠剂量时渗流失败，表现为断或缺，比高斯 CD 更陡——又一次极值。这是 MOR 的 RLS：R 受簇尺寸，L 受簇统计与 \\(G_e\\)，S 受锡吸收。</p><p>薄胶 + 自身硬掩模减轻倒塌，体积 \\(V\\) 更小，相对涨落更大，必须靠更高吸收补 \\(N\\)。High-NA 薄膜预算与随机在这里绑死，不是「金属胶自动更好」。</p><p><span class="marginnote">引用 MOR 随机结果必须写：胶厚、底层、极性、测的是 LER 还是缺孔、沾污是否在合同内。只报「比 CAR 更敏」与只报 loss 同类。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不编配体结构、不编 wt% 锡。不把实验室 LER 当量产随机窗。下一课干法显影可以与 MOR 搭配，但干法本身是显影噪声与选择比的另一章，湿法 MOR 仍适用本课团簇机制。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MOR 随机源是团簇 + 二次电子 + 光子，不是 PAG 酸计数的改名。</li><li>无长程 \\(G_a\\)；后烘不是 CAR 那颗核。</li><li>负胶悬崖口令翻转；逾渗使尾更陡。</li><li>高吸收买 \\(N\\)，团聚买地板；MC 要换抽样对象。</li><li>出处：Inpria 等公开 MOR 原理；Naulleau；主干<a href="/litho/tin-oxide-resist">锡氧胶</a>。</li></ul>',8))])}const f=r(p,[["render",c]]);export{R as __pageData,f as default};
